-- Sequences which are not based on PK, and therefore not generated by GDI

-- TODO 20090705/uma: change into PL/SQL.
-- This is an ideal candidate to include into the patch script everytime
-- But to do so, they must be changed into PL/SQL:
-- - Check if exist
-- - If not: create it. For this: must used 'execute immediate' to call
--   Data Definition Language from within PL/SQL.

-- 20.11.2009/uma:
-- However, all of those sequences are either already present in the productive
-- DB (and migrated with 1.1 installation), or new sequences will be included
-- in patch scripts in the future. Having all in one file to include with each
-- patch would be REALLY nice though, because it's easy to lose track about
-- when which sequence was added, and what actually exists in the real DB.

prompt Creating custom sequences

-- Tickets from LOGON 1.x: 42080. 
-- SHOULD: The order number must be between 10'000'000 and 19'999'999 (and may possibly even grow larger in the future).
-- REASON: The order number sent to SAP must not clash with existing order numbers from the past. By starting with 8 digits we for sure do not interfere with existing numbers in SAP.
--
-- Since LOGON 2.x: LOGON-4621.
-- Cluster 0: 10000000 to 19999999 -> see fbnl_initialdata
-- Cluster 1: 20000000 to 29999999 -> see c1_initialdata
-- Cluster 2: 30000000 to 39999999 -> c2_initialdata, once that folder/set of initialdata has been created, ca 2013
-- Cluster 3: 40000000 to 49999999 -> c3_initialdata, once that folder/set of initialdata has been created, ca 2013/2014
-- In AdN Environments, or in Crh Q env, in cases where initialdata from more than 1 cluster is loaded => last one wins. Adjust manually if NOK.
CREATE SEQUENCE SLGNC_ORDER_NUMBER START WITH 10000000 MAXVALUE 19999999 nocache;

-- Ticket 72663
-- Customer order is modeled to follow the existing LOGON order model, so the same rules will apply to
-- customer order numbers.
-- As a consequence of LOGON-4621, C1 Data Migration Task: also adjust this one per cluster, to be on the safe side (is it sent to SAP or not?)
CREATE SEQUENCE SLGNC_CUSTORDER_NUMBER START WITH 17000000 MAXVALUE 19999999 nocache;

-- About the 'nocache' option:
-- This could be a performance issue on a RAC environment. Default is caching to 20 (per node), i.e., less synchronization required.
-- Disadvantages of caching:
-- - numbers not guaranteed to be 'ordered' by creation time
-- - A gap is produced when DB or even a single app-server (db client) is restarted. With 5 app servers and 2 DB nodes, this can be significant!
-- Because these numbers have a limited range, AND are truely visible business numbers,
-- we decided that 'look nice' and 'consume only when needed' is more important than
-- performance for these 2 specific sequences.
-- All other sequences of course stay with the default of cache 20.


-- For new Sequences, use
--
-- START: 1000. Reasons:
-- - Convention for whole Logon
-- - The first 1000 records can safely be used for technical entities
--
-- MAXVALUE: 88888888888. Reasons:
-- - To immediately know, that there is no requirement (yet) about the max value
--   (and the need to extend in other systems, or implement starting-over etc)

-- Since LOGON 2.2: LOGON-6721
-- Cluster 0: 1000000000 to 1999999999 -> see fbnl_initialdata
-- Cluster 1: 2000000000 to 2999999999 -> see c1_initialdata
-- Cluster 2: 3000000000 to 3999999999 -> see c2_initialdata
CREATE SEQUENCE SLGNC_LOAD_ORDER START WITH 1000000000 MAXVALUE 1999999999;
CREATE SEQUENCE SLGNC_LOAD_ORDER_ITEM START WITH 1000000000 MAXVALUE 1999999999;

-- Ticket 42218
-- sequences for setNo of refdata which is sent to comServer
CREATE SEQUENCE SLGNC_MOPSET_LANG START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_FUNC START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_TRUCK_MAINTENANCE START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_PDA_ERROR_MESSAGE START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_PDA_MARKET_INFO START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_CURRENCY START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_FUEL_TYPE START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_WAIT_REASON_SP START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_WAIT_REASON_ST START WITH 1000 MAXVALUE 88888888888;
CREATE SEQUENCE SLGNC_MOPSET_RFIDOBJECT_TYPE START WITH 1000 MAXVALUE 88888888888;

-- sequence for eventID of outgoing events 
CREATE SEQUENCE SLGNC_LOGON_EVENTID START WITH 1000 MAXVALUE 88888888888;

