-- sequence for flat files
CREATE SEQUENCE SLGNC_LOGON_NGE_FLAT_FILE_ID START WITH 1000 MAXVALUE 9999999999;

-- sequence for the external order table of 1.4 NGE (1'000'000 for CHE, but 1'500'000 for NGE)
CREATE SEQUENCE SLGNC_EXT_ORDER_NUMBER START WITH 1000000 MAXVALUE 88888888888;

-- Sequence for transmit to SBB interchange controle reference numbers
CREATE SEQUENCE SLGNC_CIBEF102_ICR START WITH 1000000 MAXVALUE 88888888888;

--Sequence for unique identification number of load to external systems
CREATE SEQUENCE SLGNC_LOAD_NUMBER START WITH 1000 MAXVALUE 88888888888;
