------ New custom sequences during patch mode (1.x -> 1.y, as well as 2.1 (Last DB from scratch, once productive) -> 2.x)
-- ... => Add to patch, mainly, because there is no "create sequence if not exist"-mechano.

-- The assignment number, used for external systems (SAP Shipment Document). Generated independently of assignment_id, based on sequence SLGNC_ASSIGNMENT_NUMBER.
CREATE SEQUENCE SLGNC_ASSIGNMENT_NUMBER START WITH 1000 MAXVALUE 88888888888;

-------------------------------------------------------------------------------
-- Executing "custom-sequences" in each patch would result to many errors which are
-- not real errors => very dangerous when analyzing logs for errors...

-------------------------------------------------------------------------------
-- The starting sequence number(1000) is below the bigest value id of slgnc_trsp_zone_polygon, slgnc_trsp_zone_vertex
-- Increase it to bigest id value by HARD CODE following those tables
-------------------------------------------------------------------------------
DECLARE
temp1 number;
temp2 number;
BEGIN
	-- tlgnc_trsp_zone_polygon.sql the bigest id is: 1101
  execute immediate 'alter sequence slgnc_trsp_zone_polygon increment by 101';
  select slgnc_trsp_zone_polygon.nextval into temp1 from dual;
  execute immediate 'alter sequence slgnc_trsp_zone_polygon increment by 1';
  
  -- tlgnc_trsp_zone_vertex.sql the bigest id is: 1354
  execute immediate 'alter sequence slgnc_trsp_zone_vertex increment by 354'; 
  select slgnc_trsp_zone_vertex.nextval into temp2 from dual;
  execute immediate 'alter sequence slgnc_trsp_zone_vertex increment by 1';
  commit;
END;
/
show errors;